import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { generateReviewerBriefing } from "../../src/briefing/reviewer-briefing.js";

function makeMgmtDir(taskId: string, featureId: string, title: string): string {
  const dir = join(tmpdir(), `reviewer-briefing-test-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const tasksDir = join(dir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(
    join(tasksDir, `${taskId}.yaml`),
    `id: ${taskId}\ntitle: ${title}\nrepo: workflow\nstatus: in_review\n`,
    "utf-8",
  );
  return dir;
}

