1	/**
2	 * Best-effort log flush to the management repo task branch.
3	 *
4	 * Mirrors the mutateTaskYamlDirect pattern: checkout -B to force-reset to
5	 * the fetched origin tip before writing, so the push is always fast-forward
6	 * and no second fetch + rebase is required (fixes thin-pack race with syncRepo,
7	 * issue #131).
8	 */
9	
10	import { execSync } from "node:child_process";
11	import { mkdirSync, appendFileSync } from "node:fs";
12	import { join } from "node:path";
13	import { redactSecrets } from "./redact-secrets.js";
14	
15	export function flushLog(
16	  workspaceRoot: string,
17	  featureId: string,
18	  taskId: string,
19	  taskBranch: string,
20	  runStartIso: string,
21	  gitAuthorEmail: string,
22	  gitAuthorName: string,
23	  stdout: string,
24	  outcome: string,
25	  sshKeyPath: string | undefined,
26	  emit: (event: Record<string, unknown>) => void,
27	): void {
28	  try {
29	    const safeIso = runStartIso.replace(/[:.]/g, "-");
30	    const logFilename = `${safeIso}.jsonl`;
31	    const relLogPath = join("docs", "features", featureId, "logs", taskId, logFilename);
32	    const logPath = join(workspaceRoot, relLogPath);
33	
34	    const env = {
35	      ...process.env,
36	      GIT_AUTHOR_NAME: gitAuthorName,
37	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
38	      GIT_COMMITTER_NAME: gitAuthorName,
39	      GIT_COMMITTER_EMAIL: gitAuthorEmail,
40	      ...(sshKeyPath ? { GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new` } : {}),
41	    };
42	    const gitOpts = { env, stdio: "pipe" as const, timeout: 30_000 };
43	
44	    // Step 1: Move to the task branch tip BEFORE writing any files.
45	    // Use checkout -B to force-reset to the fetched origin tip — mirrors mutateTaskYamlDirect.
46	    // This guarantees fully-materialized objects (no thin-pack gaps) and eliminates the
47	    // need for a second fetch + rebase, which races with syncRepo's periodic git fetch.
48	    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, gitOpts);
49	    execSync(`git -C "${workspaceRoot}" checkout -- .`, gitOpts);
50	    execSync(`git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);
51	
52	    // Step 2: Write the log file (directory may not exist on this branch yet).
53	    const logsDir = join(workspaceRoot, "docs", "features", featureId, "logs", taskId);
54	    mkdirSync(logsDir, { recursive: true });
55	    appendFileSync(logPath, JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n");
56	    if (stdout) {
57	      const safe = redactSecrets(stdout);
58	      appendFileSync(logPath, safe.endsWith("\n") ? safe : safe + "\n");
59	    }
60	    appendFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n");
61	
62	    // Step 3: Commit and push. No second fetch or rebase needed — we already
63	    // started from the exact origin tip, so the push is always fast-forward.
64	    // A rejected push (log_flush_failed) is acceptable; log is telemetry only.
65	    execSync(`git -C "${workspaceRoot}" add "${relLogPath}"`, gitOpts);
66	    execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
67	    execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
68	  } catch (e) {
69	    emit({ type: "log_flush_failed", task_id: taskId, feature_id: featureId, details: String(e) });
70	  }
71	}
72

